// Check line_verify.py exit code and stdout
if ($input.item.json.exitCode !== 0) {
  // line_verify failed — treat as invalid, stop (LINE already got 200)
  return null;
}
let result;
try {
  result = JSON.parse($input.item.json.stdout);
} catch(e) {
  return null;
}
if (!result.valid) {
  // Invalid signature — stop workflow silently
  return null;
}
// Valid signature — pass original webhook data downstream
return { json: $('LINE Webhook').first().json };

const data = $input.item.json;
const body = data.body || {};
const events = body.events || [];
if (events.length === 0) return null; // webhook verification ping
const event = events[0];
// Only handle text messages
if (event.type !== 'message' || !event.message || event.message.type !== 'text') return null;
return {
  json: {
    lineUserId: event.source && event.source.userId || '',
    messageText: event.message.text || '',
    replyToken: event.replyToken || ''
  }
};

let chunks = [];
if ($input.item.json.exitCode === 0) {
  try { chunks = JSON.parse($input.item.json.stdout); } catch(e) { chunks = []; }
}
if (!Array.isArray(chunks)) chunks = [];
const msgData = $('Parse Message').first().json;
return {
  json: {
    lineUserId: msgData.lineUserId,
    messageText: msgData.messageText,
    replyToken: msgData.replyToken,
    chunks: chunks,
    chunkIds: chunks.map(function(c) { return c.chunk_id; })
  }
};

const authResult = $input.item.json;
const msgData = $('Parse Message').first().json;

if (!authResult.authorized) {
  // User not in allowed_users — send LINE reply and stop
  try {
    await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.line.me/v2/bot/message/reply',
      headers: {
        'Authorization': 'Bearer ' + process.env.LINE_CHANNEL_ACCESS_TOKEN,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        replyToken: msgData.replyToken,
        messages: [{ type: 'text', text: '您無使用權限' }]
      })
    });
  } catch(e) {
    // Ignore reply error — workflow stops regardless
  }
  return null;
}

// Authorized — combine data and write prompt_builder temp file
const chunksData = $('Parse Chunks').first().json;
const sessionData = $('Query conversation_sessions').first().json;
const turns = Array.isArray(sessionData.turns) ? sessionData.turns : [];
const history = turns.slice(-6); // last 3 rounds

const os = require('os');
const fs = require('fs');
const path = require('path');

const promptInput = {
  question: chunksData.messageText,
  chunks: chunksData.chunks || [],
  history: history
};
const tmpPrompt = path.join(os.tmpdir(), 'n8n_prompt_' + Date.now() + '_' + Math.random().toString(36).slice(2) + '.json');
fs.writeFileSync(tmpPrompt, JSON.stringify(promptInput), 'utf8');

return {
  json: {
    lineUserId: chunksData.lineUserId,
    messageText: chunksData.messageText,
    replyToken: chunksData.replyToken,
    chunks: chunksData.chunks,
    chunkIds: chunksData.chunkIds,
    history: history,
    sessionTurns: turns,
    _tmp_prompt: tmpPrompt
  }
};

// Clean up temp file
const fs = require('fs');
try { fs.unlinkSync($('Check Auth').first().json._tmp_prompt); } catch(e) {}

if ($input.item.json.exitCode !== 0) {
  throw new Error('prompt_builder.py failed (exit ' + $input.item.json.exitCode + '): ' + ($input.item.json.stderr || ''));
}
let promptData;
try { promptData = JSON.parse($input.item.json.stdout); } catch(e) {
  throw new Error('Failed to parse prompt_builder.py output: ' + e.message);
}
const prevData = $('Check Auth').first().json;
return {
  json: {
    lineUserId: prevData.lineUserId,
    messageText: prevData.messageText,
    replyToken: prevData.replyToken,
    chunkIds: prevData.chunkIds,
    sessionTurns: prevData.sessionTurns,
    systemPrompt: promptData.system || '',
    userPrompt: promptData.prompt || ''
  }
};

const response = $input.item.json;
// Ollama /api/chat response: {message: {role, content}, done, ...}
const answer = (response.message && response.message.content) || response.response || '';
const prevData = $('Parse Prompt').first().json;
return {
  json: {
    lineUserId: prevData.lineUserId,
    messageText: prevData.messageText,
    replyToken: prevData.replyToken,
    chunkIds: prevData.chunkIds,
    sessionTurns: prevData.sessionTurns,
    answer: answer || '抱歉，目前無法生成回答，請稍後再試。'
  }
};

const extractData = $('Extract Answer').first().json;
const msgData = $('Parse Message').first().json;

// Build updated turns: old turns + new user/assistant turn, keep last 10 (5 rounds)
const oldTurns = Array.isArray(extractData.sessionTurns) ? extractData.sessionTurns : [];
const newTurns = oldTurns.concat([
  { role: 'user', content: extractData.messageText },
  { role: 'assistant', content: extractData.answer }
]).slice(-10);

// Format chunk_ids as PostgreSQL UUID array literal: {uuid1,uuid2,...}
// Required for ::uuid[] cast in INSERT qa_logs
const chunkIds = Array.isArray(extractData.chunkIds) ? extractData.chunkIds : [];
const chunkIdsArray = chunkIds.length > 0 ? '{' + chunkIds.join(',') + '}' : '{}';

return {
  json: {
    lineUserId: extractData.lineUserId,
    messageText: extractData.messageText,
    answer: extractData.answer,
    newTurnsJson: JSON.stringify(newTurns),
    chunkIdsArray: chunkIdsArray
  }
};
